INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "蜀命周庠充永平节度使。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p009·原文件第24行", "note": "原文：丁巳，蜀以司徒兼门下侍郎、同平章事周庠同平章事，充永平节度使。；核对说明：底本前后重见同平章事，保留原字；确定本段新记充永平节度使，未据重复官衔另造二次授相。", "status": "draft", "id": "1148f350-2e25-5cde-9669-c5ccdd1bb16d", "subject_id": "9872c06d-6054-5128-b808-fbc26392a2af", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "920年六月丁巳", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p009·原文件第24行", "note": "原文：丁巳，蜀以司徒兼门下侍郎、同平章事周庠同平章事，充永平节度使。；核对说明：按主书本段纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "48969c53-931d-5d05-a66b-c80db5372879", "subject_id": "9872c06d-6054-5128-b808-fbc26392a2af", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记周庠：充永平节度使、保有同平章事衔者。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p009·原文件第24行", "note": "原文：丁巳，蜀以司徒兼门下侍郎、同平章事周庠同平章事，充永平节度使。；核对说明：与既有规范名合并；繁简或异体仅用于实体匹配，引用保留原字。", "status": "draft", "id": "7c103a00-a77a-5fc2-bb97-702c36fcb811", "subject_id": "fb440e5b-1571-58ce-8ca0-85a0e1b24122", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "周庠：充永平节度使、保有同平章事衔者。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p009·原文件第24行", "note": "原文：丁巳，蜀以司徒兼门下侍郎、同平章事周庠同平章事，充永平节度使。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "74a26990-1444-5f42-beed-a681ff7ca791", "subject_id": "4e840d96-2eb7-5e00-b73d-f234a9f42dfc", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "description", "claim_text": "梁任刘鄩为河东道招讨使，率尹皓等攻同州。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p010·原文件第25行", "note": "原文：帝以泰宁节度使刘鄩为河东道招讨使，帅感化节度使尹皓、静胜节度使温昭图、庄宅使段凝攻同州。；核对说明：主书按本段官衔录入；温昭